B.amJ=s(["\u0627\u0644\u0645\u0648\u0642\u0639 \u0635\u0627\u0631 \u0639\u0644\u0649 \u0639\u0646\u0648\u0627\u0646\u0647 \u0627\u0644\u062e\u0627\u0635: ibnalshabira.com","\u0634\u0627\u0634\u0627\u062a \u062a\u0631\u062d\u064a\u0628 \u062c\u062f\u064a\u062f\u0629.","\u0632\u0631 \xab\u062d\u0641\u0638\xbb \u0648\u0627\u0636\u062d \u0644\u0627\u0633\u0645\u0643 \u0623\u0648 \u0643\u0646\u064a\u062a\u0643 \u0641\u064a \u0635\u0641\u062d\u0629 \u0627\u0644\u062d\u0633\u0627\u0628.","\u0628\u0637\u0627\u0642\u0629 \xab\u0627\u0644\u0645\u0635\u062d\u0641\xbb \u0630\u0647\u0628\u064a\u0629 \u0641\u064a \xab\u0627\u0644\u0645\u0632\u064a\u062f\xbb\u060c \u0648\u062e\u064a\u0627\u0631 \xab\u062f\u0627\u0643\u0646 \u0628\u0639\u062f \u0627\u0644\u0645\u063a\u0631\u0628\xbb \u0635\u0627\u0631 \u062f\u0627\u062e\u0644 \u0642\u0627\u0626\u0645\u0629 \xab\u0627\u0644\u0645\u0638\u0647\u0631\xbb.","\u0645\u0631\u0628\u0639\u0627\u062a \u0627\u0644\u0623\u0630\u0643\u0627\u0631 \u062a\u064f\u0638\u0647\u0631 \u0643\u0645 \u0623\u062a\u0645\u0645\u062a \u0627\u0644\u064a\u0648\u0645.","\u0627\u0633\u062d\u0628 \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629 \u0644\u0644\u0623\u0633\u0641\u0644 \u0644\u062c\u0644\u0628 \u0627\u0644\u062c\u062f\u064a\u062f.","\u0644\u0644\u0645\u0634\u0631\u0641\u064a\u0646: \u0625\u0636\u0627\u0641\u0629 \u0628\u0627\u0628 \u062c\u062f\u064a\u062f \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0645\u0631\u0627\u062c\u0639\u0629\u060c \u0648\u0627\u062e\u062a\u064a\u0627\u0631 \u0631\u0645\u0632 \u0644\u0643\u0644 \u0628\u0627\u0628 \u0645\u0646 \u0645\u062c\u0645\u0648\u0639\u0629 \u0643\u0628\u064a\u0631\u0629.","\u0634\u0627\u0634\u0629 \u062a\u062d\u0645\u064a\u0644 \u0628\u0627\u0644\u0634\u0639\u0627\u0631 \u0639\u0646\u062f \u0641\u062a\u062d \u0627\u0644\u0645\u0648\u0642\u0639."],t.s)
B.aOm=new A.a6("3.3.0",B.amJ)
B.alR=s(["\u0627\u0644\u0645\u0635\u062d\u0641 \u0628\u062e\u0637 \u0645\u0635\u062d\u0641 \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0648\u0646\u0635\u0651\u0647 \u0627\u0644\u0631\u0633\u0645\u064a: \u0639\u0644\u0627\u0645\u0627\u062a \u0627\u0644\u0648\u0642\u0641 \u0648\u0627\u0644\u062a\u0634\u0643\u064a\u0644 \u0641\u064a \u0645\u0648\u0627\u0636\u0639\u0647\u0627 \u0627\u0644\u0635\u062d\u064a\u062d\u0629.","\u062f\u0627\u062e\u0644 \u0627\u0644\u0645\u0635\u062d\u0641: \u0632\u0631 \u0625\u0639\u062f\u0627\u062f\u0627\u062a (\u0635\u0641\u062d\u0629 \u0644\u064a\u0644\u064a\u0629\u060c \u062e\u062a\u0645\u0629 \u0628\u0648\u0650\u0631\u062f \u064a\u0648\u0645\u064a)\u060c \u0648\xab\u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0641\u0642\u0637\xbb \u0628\u0636\u063a\u0637\u062a\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u0635\u0641\u062d\u0629\u060c \u0648\u0645\u0634\u0627\u0631\u0643\u0629 \u0627\u0644\u0622\u064a\u0629.","\u0627\u0644\u0634\u0631\u064a\u0637 \u0627\u0644\u0633\u0641\u0644\u064a: \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629\u060c \u0627\u0644\u0643\u062a\u0628\u060c \u0627\u0644\u0645\u062d\u0641\u0648\u0638\u0627\u062a\u060c \u0627\u0633\u0623\u0644 \u0627\u0644\u0634\u064a\u062e\u060c \u0627\u0644\u0645\u0634\u0627\u064a\u062e \u0627\u0644\u062b\u0642\u0627\u062a\u060c \u0627\u0644\u0645\u0632\u064a\u062f (\u0648\xab\u0627\u0644\u0625\u062f\u0627\u0631\u0629\xbb \u0644\u0644\u0645\u0634\u0631\u0641\u064a\u0646).","\u0627\u0644\u0645\u0635\u062d\u0641 \u0648\u0627\u0644\u0623\u0630\u0643\u0627\u0631 \u0628\u0637\u0627\u0642\u062a\u0627\u0646 \u0641\u064a \xab\u0627\u0644\u0645\u0632\u064a\u062f\xbb \u0628\u0639\u062f \u0628\u0637\u0627\u0642\u0629 \u0642\u0631\u0627\u0621\u062a\u0643.","\u0627\u0644\u0623\u0630\u0643\u0627\u0631 \u0628\u0634\u0643\u0644 \u062c\u062f\u064a\u062f: \u0623\u0631\u0628\u0639\u0629 \u0645\u0631\u0628\u0639\u0627\u062a (\u0627\u0644\u0635\u0628\u0627\u062d\u060c \u0627\u0644\u0645\u0633\u0627\u0621\u060c \u0627\u0644\u0646\u0648\u0645\u060c \u0628\u0639\u062f \u0627\u0644\u0635\u0644\u0627\u0629) \u062b\u0645 \u0627\u0644\u0641\u0647\u0631\u0633.","\u0627\u0644\u0645\u0631\u0626\u064a\u0627\u062a \u0644\u0627 \u062a\u062e\u062a\u0641\u064a: \u062a\u0628\u0642\u0649 \u0622\u062e\u0631 \u0642\u0627\u0626\u0645\u0629 \u0645\u062d\u0641\u0648\u0638\u0629 \u0625\u0630\u0627 \u062a\u0639\u0630\u0651\u0631 \u062c\u0644\u0628 \u0627\u0644\u062c\u062f\u064a\u062f.","\u0627\u0644\u0645\u0648\u0642\u0639 \u064a\u0641\u062a\u062d \u0623\u0633\u0631\u0639: \u062a\u0638\u0647\u0631 \u0623\u062d\u062f\u062b \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0641\u0648\u0631\u0627\u064b \u0648\u062a\u064f\u062d\u0645\u064e\u0651\u0644 \u0628\u0642\u064a\u0629 \u0627\u0644\u0645\u0643\u062a\u0628\u0629 \u0641\u064a \u0627\u0644\u062e\u0644\u0641\u064a\u0629.","\u0632\u0631 \xab\u0623\u0631\u0633\u0644 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0644\u0635\u062f\u064a\u0642\xbb \u0641\u064a \xab\u0627\u0644\u0645\u0632\u064a\u062f\xbb."],t.s)
